-- Reproduce the legacy default grants in the second tenant so Migration 017
-- proves that it removes them everywhere without deleting the role.
insert into public.role_permissions (school_id, role_id, permission_id)
select role.school_id, role.id, permission.id
from public.roles as role
join public.permissions as permission
  on permission.code in ('school.view', 'branches.view')
where role.school_id = '10000000-0000-4000-8000-000000000002'
  and role.code = 'guardian';

